    String changed=owned.get(13);var changedLease=repo.claim(changed);db.update("UPDATE b_market_order SET review_required=TRUE,last_error='OWNED_FACT_CONFLICT' WHERE order_id=?",changedLease.request().orderId());check(!repo.authorize(changedLease)&&taskState(db,changed).equals("REVIEW_REQUIRED")&&count(db,"SELECT COUNT(*) FROM b_sim_refund WHERE refund_id=?",changed)==0,"qualification is rechecked after query before execute");held(db,changed);
    String after=owned.get(14);var afterLease=repo.claim(after);var afterFact=channel.execute(afterLease.request());db.update("UPDATE b_market_order SET review_required=TRUE,last_error='OWNED_FACT_CONFLICT' WHERE order_id=?",afterLease.request().orderId());repo.finish(afterLease,afterFact);check(fund(db,after).equals("SUCCEEDED")&&taskState(db,after).equals("REVIEW_REQUIRED"),"post-channel contradiction retains actual refunded funds while quarantining");held(db,after);
