    String duplicateNotice=db.queryForObject("SELECT notification_id FROM b_sim_refund_notification WHERE refund_id=?",String.class,dropped);db.update("UPDATE b_sim_refund_notification SET state='READY',next_attempt_ms=-1,lease_token=NULL,lease_until_ms=NULL WHERE notification_id=?",duplicateNotice);fault.mode="CONFLICT";service.notices(1);check(fund(db,dropped).equals("SUCCEEDED")&&taskState(db,dropped).equals("REVIEW_REQUIRED")&&count(db,"SELECT COUNT(*) FROM b_sim_refund_notification WHERE notification_id=? AND state='REVIEW_REQUIRED'",duplicateNotice)==1,"same version differing fact quarantines without undoing funds");fault.mode="NORMAL";
